/**
 * BUG-023：`nudo:interface-drift` 对**函数体内**的调用点恒不触发 ⇒ 陈旧
 * `@generated` 段零告警（假绿）。
 *
 * 根因：drift 的「今日域」证据（AbsCallRecord）收集窗口只包**模块顶层**
 * 求值 ⇒ 函数体内的调用点（绝大多数真实调用点）从不进证据表
 * ⇒ `check-interface-drift` 的 `evidence.length === 0 → continue` 静默跳过。
 *
 * 本套件钉：同一份陈旧生成段，
 * - 调用点在**函数体内**（`caller(){ return add(1,2) }`）→ 必须报 drift；
 * - 调用点在**模块顶层** → 同样报 drift（既有行为，对照组）；
 * - 证据确实来自实参域（`lit(9)` vs 今日 `1/2`）。
 */
import { describe, it, expect, beforeEach } from "vitest";
import { checkSource, pTrue } from "../index.ts";
import { resetCheckSourceMemo } from "../check.ts";
import { resetGeneralizeMemo } from "../generalize.ts";
import { takeInterfaceDiags } from "../interface.ts";
import { takeRefineDiags } from "../refine.ts";
import { makeFiles } from "./nudo-constraints.ts";

const GEN = `import { fn, lit } from "@nudojs/core";
// @generated by nudo — do not edit; regenerate with \`nudo contract --emit\`
// source: inner.js:add
export const add = fn({ a: lit(9), b: lit(9) }, lit(9));
`;

function check(src: string) {
  const { loadModule } = makeFiles({ "/t/area.nudo.js": GEN });
  return checkSource("/t/area.js", src, pTrue, {
    loadModule,
    fromFile: "/t/area.js",
  });
}

describe("BUG-023 drift 的今日域证据包含函数体内的调用点", () => {
  beforeEach(() => {
    resetCheckSourceMemo();
    resetGeneralizeMemo();
    takeInterfaceDiags();
    takeRefineDiags();
  });

  it("调用点在函数体内 → 报 drift（旧口径零告警）", () => {
    const r = check(`
export function add(a, b) {
  return a + b;
}
export function caller() {
  return add(1, 2);
}
`);
    const drifts = r.issues.filter((i) => i.code === "nudo:interface-drift");
    const params = drifts.map((i) => i.message.match(/\[(\w+)\]/)?.[1]);
    // 参数位 a、b 的快照 lit(9) ≠ 今日实参 1 / 2
    expect(params).toContain("a");
    expect(params).toContain("b");
    expect(drifts.every((i) => i.severity === "warning")).toBe(true);
    // generated 不执法：warning 不破门禁
    expect(r.ok).toBe(true);
  });

  it("对照组：调用点在模块顶层 → 同样报 drift", () => {
    const r = check(`
export function add(a, b) {
  return a + b;
}
add(1, 2);
`);
    const drifts = r.issues.filter((i) => i.code === "nudo:interface-drift");
    expect(drifts.map((i) => i.message.match(/\[(\w+)\]/)?.[1])).toContain("a");
    expect(drifts.map((i) => i.message.match(/\[(\w+)\]/)?.[1])).toContain("b");
  });

  it("快照与函数体内调用域一致 → 无 drift（没有把窗口扩大变成误报）", () => {
    const { loadModule } = makeFiles({
      "/t/area.nudo.js": `import { fn, lit } from "@nudojs/core";
// @generated by nudo — do not edit
export const add = fn({ a: lit(1), b: lit(2) }, lit(3));
`,
    });
    const r = checkSource(
      "/t/area.js",
      `
export function add(a, b) {
  return a + b;
}
export function caller() {
  return add(1, 2);
}
`,
      pTrue,
      { loadModule, fromFile: "/t/area.js" },
    );
    expect(r.issues.filter((i) => i.code === "nudo:interface-drift")).toEqual([]);
  });
});
